"""Writes generated byte arrays as raw files plus #embed wrappers, so the compiler never parses a hex text array."""
from pathlib import Path

WRAPPER_OPEN = '#pragma clang diagnostic push\n#pragma clang diagnostic ignored "-Wc++26-extensions"\n'
WRAPPER_CLOSE = '#pragma clang diagnostic pop\n'
EMBED_MINIMUM = 256  # a smaller array stays inline: its own file costs more than the lines it saves


def write_if_changed(path, data):
    """Writes `data` unless `path` already holds it: unchanged generated files keep their timestamps (ninja restat)."""
    path = Path(path)
    if not path.is_file() or path.read_bytes() != data:
        path.write_bytes(data)


def embed_array(declaration, file):
    """C++ for one array initialised from the bytes of `file`, beside the including file (a subdirectory is fine).
    Wrap one or more of these in WRAPPER_OPEN/WRAPPER_CLOSE."""
    return f'{declaration}{{\n#embed "{file}"\n}};\n'


def embed_arrays(items):
    """WRAPPER_OPEN, one embed_array per `(declaration, file)` pair, WRAPPER_CLOSE."""
    return WRAPPER_OPEN + ''.join(embed_array(declaration, file) for declaration, file in items) + WRAPPER_CLOSE


def write_embedded_arrays(directory, arrays):
    """Writes `<directory>/<name>.bin` for each `(declaration, name, data)` and returns the C++ initialising them
    under one wrapper; the including file sits beside `directory`."""
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    items = []
    for declaration, name, data in arrays:
        write_if_changed(directory / f'{name}.bin', bytes(data))
        items.append((declaration, f'{directory.name}/{name}.bin'))
    return embed_arrays(items)


def write_embedded_array(path, comment, declaration, data):
    """`path` becomes the .inc wrapper; `<stem>.bin` beside it holds `data`. `comment` is zero or more
    complete `//` lines (each ending in a newline)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    write_if_changed(path.with_suffix('.bin'), bytes(data))
    write_if_changed(path, (comment + embed_arrays([(declaration, path.stem + '.bin')])).encode('utf-8'))


def array_block(directory, arrays, inline):
    """`(text, files)` for `(declaration, name, data)` arrays in order. Arrays of at least EMBED_MINIMUM bytes are
    embedded from `<directory>/<name>.bin` (`files` maps each path to its bytes; see write_files); the others are
    rendered by `inline(declaration, data)` (text ending in a newline). One wrapper spans from the first embedded
    array to the last; there is none without an embedded array."""
    directory = Path(directory)
    big = [index for index, (_, _, data) in enumerate(arrays) if len(data) >= EMBED_MINIMUM]
    out, files = [], {}
    for index, (declaration, name, data) in enumerate(arrays):
        if big and index == big[0]:
            out.append(WRAPPER_OPEN)
        if index in big:
            files[directory / f'{name}.bin'] = bytes(data)
            out.append(embed_array(declaration, f'{directory.name}/{name}.bin'))
        else:
            out.append(inline(declaration, data))
        if big and index == big[-1]:
            out.append(WRAPPER_CLOSE)
    return ''.join(out), files


def write_files(files):
    """Writes a `{path: bytes}` map, creating directories and leaving unchanged files alone."""
    for path, data in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        write_if_changed(path, data)
